window.UNION_IMAGES={
hero:"data:image/webp;base64,",
repair:"data:image/webp;base64,",
led:"data:image/webp;base64,",
install:"data:image/webp;base64,"
};
document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-photo]").forEach(img=>{const src=window.UNION_IMAGES[img.dataset.photo];if(src)img.src=src;}));